import{_ as t,c as o,o as a,aj as r}from"./chunks/framework.Id7s26SP.js";const m=JSON.parse('{"title":"Interface: YjsPersistenceContext","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/YjsPersistenceContext.md","filePath":"reference/js-bao-wss-client/api/interfaces/YjsPersistenceContext.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/YjsPersistenceContext.md"};function s(c,e,d,i,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / YjsPersistenceContext</p><h1 id="interface-yjspersistencecontext" tabindex="-1">Interface: YjsPersistenceContext <a class="header-anchor" href="#interface-yjspersistencecontext" aria-label="Permalink to “Interface: YjsPersistenceContext”">​</a></h1><p>Context passed to the Yjs persistence factory.</p><p><code>documentId</code>, <code>documentFormat</code> and <code>epoch</code> describe what the store the factory is being asked for holds. All three are optional, so a context literal a caller declared for itself before they existed still satisfies this type.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="appid" tabindex="-1">appId <a class="header-anchor" href="#appid" aria-label="Permalink to “appId”">​</a></h3><blockquote><p><strong>appId</strong>: <code>string</code></p></blockquote><p>The application ID</p><hr><h3 id="documentformat" tabindex="-1">documentFormat? <a class="header-anchor" href="#documentformat" aria-label="Permalink to “documentFormat?”">​</a></h3><blockquote><p><code>optional</code> <strong>documentFormat?</strong>: <code>1</code> | <code>2</code></p></blockquote><p><code>2</code> for a large document, <code>1</code> for an ordinary one.</p><p>Absent when nothing local knows the format yet — the very first open of a document created elsewhere, whose format the client settles from the document read that open already makes. It is never guessed: a factory that branches on this is not told a large document is an ordinary one. The store name is the plain document id in that case either way, because a document this client has never held has no epoch to scope it to.</p><hr><h3 id="documentid" tabindex="-1">documentId? <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId?”">​</a></h3><blockquote><p><code>optional</code> <strong>documentId?</strong>: <code>string</code></p></blockquote><p>The document the store belongs to — the plain id, without the epoch suffix the store name may carry. Use this to key anything that is about the DOCUMENT rather than about one of its stores.</p><hr><h3 id="epoch" tabindex="-1">epoch? <a class="header-anchor" href="#epoch" aria-label="Permalink to “epoch?”">​</a></h3><blockquote><p><code>optional</code> <strong>epoch?</strong>: <code>number</code> | <code>null</code></p></blockquote><p>The epoch the store name is scoped to, or <code>null</code> when the name is the plain document id — an ordinary document, or a large one that has not rotated yet.</p><hr><h3 id="userid" tabindex="-1">userId <a class="header-anchor" href="#userid" aria-label="Permalink to “userId”">​</a></h3><blockquote><p><strong>userId</strong>: <code>string</code></p></blockquote><p>The current user&#39;s ID (or &quot;anon&quot; if not authenticated)</p>',27)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
